rss.channel:
  {{ .Title }} — {{ .Site.Title }}
  {{ .Permalink }}
  Sets tagged {{ .Title }}
  Hugo -- gohugo.io
  {{ range .Pages }}


    {{ partial "set-title.html" . }}
    {{ .Permalink }}
    {{ .Date.Format "Mon, 02 Jan 2006 15:04:05 -0700" | safeHTML }}
    {{ .Permalink }}

	{{ with .Params.embed }}
  	 {{ if eq .platform "mixcloud" }}
    	   <p><a href="https://www.mixcloud.com{{ .feed }}">Listen on Mixcloud</a></p>
  	  {{ else if eq .platform "soundcloud" }}
    	   <p><a href="{{ .url }}">Listen on SoundCloud</a></p>
  	 {{ end }}
	{{ end }}
	{{ .Summary | html }}


  {{ end }}
